local FishingMgr = import('Game.UI.Fishing.FishingMgr')
local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
local fishingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)

----------------------------------------

---@class BtnLeaveService
local BtnLeaveService = Class("BtnLeaveService")

function BtnLeaveService.new(from)
    local obj = BtnLeaveService.New()
    obj.luaDialog = from
    for k, v in pairs(from) do
        obj[k]=v
    end
    obj.BtnEventProxy = UIEventProxy.Create(obj.BtnLeave.gameObject)
    return obj
end

function BtnLeaveService:UpdateInfo()
    local curReelId = fishingComponent:GetCurEquipReelId(self.placeId)
    local vo = FishingUtils.GetFishingReelVo(curReelId)
    if vo then
        CfUtils.FillImage(self.ImgPart_1, vo.pic.."1.png")
        CfUtils.FillImage(self.ImgPart_2, vo.pic.."2.png")
        CfUtils.FillImage(self.ImgPart_3, vo.pic.."3.png")
    end
end

function BtnLeaveService:ShowMe()
    self:SetBtnActive(true)
    CfUtils.SetActive(self.BtnLeave, true)
    KTool.SetActive(self.BtnLeave.transform:Find("ImgGroup/UIFX_FishPoolGoFishingDialogAutoFishPanel"), FishingUtils.IsAutoing())
    KTool.SetActive(self.FishingDefaultPanel, true)
    local canvasGroup = KTool.GetComponent(self.FishingDefaultPanel.gameObject, typeof(CS.UnityEngine.CanvasGroup))
    canvasGroup.alpha = 1
end

function BtnLeaveService:HideMe()
    self:SetBtnActive(false)
    CfUtils.SetActive(self.BtnLeave, false)
end

function BtnLeaveService:OnUpdate()
    self:UpdataReelPage()
end

function BtnLeaveService:OnPointerDown()
    if FishingUtils.IsAutoing() then
        return
    end
    FishingMgr:GetInstance():SetTieRod(true)
end

function BtnLeaveService:OnPointerUp()
    if FishingUtils.IsAutoing() then
        return
    end
    FishingMgr:GetInstance():SetTieRod(false)
end

function BtnLeaveService:SetBtnActive(flag)
    if flag then
        self.BtnEventProxy.onPointerDown = Bind(self, self.OnPointerDown)
        self.BtnEventProxy.onPointerUp = Bind(self, self.OnPointerUp)
    else
        self.BtnEventProxy.onPointerDown = nil
        self.BtnEventProxy.onPointerUp = nil
    end
end

--刷新卷线仑图标旋转
function BtnLeaveService:UpdataReelPage()
    local speed = FishingMgr:GetInstance():GetCurSpeed()
    local normalTieRod = FishingMgr:GetInstance():GetTieRod() and -1 or 1

    local ang = FishingUtils.GetReelRotTieSpeed() --15 * 2
    if normalTieRod == -1 then
        ang = FishingUtils.GetReelRotNotTieSpeed() ---15
    end
    ang = self.ImgPart_3.localRotation.eulerAngles.z + ang
    self.ImgPart_3.transform.localRotation = Quaternion.Euler(0, 0, ang)
end

return BtnLeaveService